$ErrorActionPreference = 'Stop'
if (-not (Test-Path 'package.json')) {
    Write-Host 'ERROR: run from project root.' -ForegroundColor Red
    exit 1
}
$files = @{}
$files['lib/db/types.ts'] = ''
$files['lib/db/audit.ts'] = ''
$files['lib/utils/format.ts'] = ''
$files['components/app/page-header.tsx'] = ''
$files['components/app/empty-state.tsx'] = ''
$files['components/app/filter-chips.tsx'] = ''
$files['components/app/attribution.tsx'] = ''
$files['components/app/vertical-badge.tsx'] = ''
$files['components/app/lifecycle-badge.tsx'] = ''
$files['app/(app)/accounts/actions.ts'] = ''
$files['app/(app)/accounts/page.tsx'] = ''
$files['app/(app)/accounts/_components/accounts-table.tsx'] = ''
$files['app/(app)/accounts/new/page.tsx'] = ''
$files['app/(app)/accounts/_components/account-form.tsx'] = ''
$files['app/(app)/accounts/[id]/page.tsx'] = ''
$files['app/(app)/accounts/[id]/edit/page.tsx'] = ''
$files['app/(app)/contacts/actions.ts'] = ''
$files['app/(app)/contacts/page.tsx'] = ''
$files['app/(app)/contacts/_components/contacts-table.tsx'] = ''
$files['app/(app)/contacts/new/page.tsx'] = ''
$files['app/(app)/contacts/_components/contact-form.tsx'] = ''
$files['app/(app)/contacts/[id]/page.tsx'] = ''
$files['app/(app)/contacts/[id]/edit/page.tsx'] = ''
$files['app/(app)/import/actions.ts'] = ''
$files['app/(app)/import/page.tsx'] = ''
$files['app/(app)/import/_components/import-wizard.tsx'] = ''
$files['app/(app)/dashboard/page.tsx'] = ''

Write-Host '-> Day 3 code drop' -ForegroundColor Cyan
foreach ($path in $files.Keys) {
    $content = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($files[$path]))
    $dir = Split-Path -Parent $path
    if ($dir -and -not (Test-Path $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
    $fullPath = Join-Path -Path (Get-Location) -ChildPath $path
    [System.IO.File]::WriteAllText($fullPath, $content, [System.Text.UTF8Encoding]::new($false))
    Write-Host ('  + ' + $path) -ForegroundColor Green
}

Write-Host ''
Write-Host '====================================' -ForegroundColor Green
Write-Host '  Day 3 files written' -ForegroundColor Green
Write-Host '====================================' -ForegroundColor Green
Write-Host ''
Write-Host 'Test: npm run dev  ->  http://localhost:3000/accounts' -ForegroundColor Cyan
